  var STOP = {
    de:1, la:1, el:1, los:1, las:1, un:1, una:1, para:1, por:1, con:1, sin:1,
    del:1, al:1, y:1, o:1, a:1, en:1, x:1, kg:1, gr:1, g:1, ml:1, lt:1, l:1,
    und:1, caja:1, cajas:1, botella:1, bolsa:1, balde:1, familiar:1, lista:1,
    consumir:1, diluir:1, sabor:1, uht:1, unds:1, cj:1, pack:1, prom:1,
    promocion:1, promo:1, paquete:1, pqt:1, paq:1, grs:1, gramos:1, cc:1,
    trad:1, tradicional:1, finas:1, fina:1, sand:1, sandwich:1, molde:1,
    grande:1, chico:1, chef:1, blister:1, granel:1
  };

  var KEY_WORDS = {
    edam:1, gouda:1, danbo:1, andino:1, parmesano:1, fresco:1, yopi:1,
    sbelt:1, griego:1, manjar:1, fudge:1, jamonada:1, mantequilla:1,
    margarina:1, chocolate:1, vainilla:1, fresa:1, natural:1, nutrilac:1,
    preferida:1, suiza:1, watts:1, light:1, enter:1, descremada:1
  };

  function expand(s) {
    s = String(s || '').toLowerCase();
    s = s.replace(/\bq\.\s*/g, 'queso ');
    s = s.replace(/\bq\s+/g, 'queso ');
    s = s.replace(/\bj\.\s*/g, 'jamon ');
    s = s.replace(/\bj\s+/g, 'jamon ');
    s = s.replace(/\bmant\.\s*/g, 'mantequilla ');
    s = s.replace(/\bmarg\.\s*/g, 'margarina ');
    s = s.replace(/\byog\.\s*/g, 'yogurt ');
    s = s.replace(/\bb\.\s*nutritiva\b/g, 'bebida nutritiva ');
    s = s.replace(/\bb\.\s*/g, 'bebida ');
    s = s.replace(/\bleche\s+uht\b/g, 'leche ');
    s = s.replace(/\bsin\s+lactosa\b/g, 'sin lactosa ');
    return s;
  }

  function norm(s) {
    if (!s) return '';
    s = expand(s);
    s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    s = s.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
    return s;
  }

  function tokens(s) {
    var parts = norm(s).split(' ');
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var t = parts[i];
      if (t && t.length > 1 && !STOP[t]) out.push(t);
    }
    return out;
  }

  for (var i = 0; i < CATALOG.length; i++) {
    var e = CATALOG[i];
    e._tok = tokens((e.b || '') + ' ' + (e.d || '') + ' ' + (e.t || ''));
    if (e.i) e.i = String(e.i).replace('Media//', 'Media/');
  }

  function findImage(descripcion, marca, opts) {
    opts = opts || {};
    var minScore = opts.minScore != null ? opts.minScore : 0.45;
    var minInter = opts.minInter != null ? opts.minInter : 2;
    var query = (marca ? marca + ' ' : '') + (descripcion || '');
    var qt = tokens(query);
    if (!qt.length) return null;

    var qtSet = {};
    for (var i = 0; i < qt.length; i++) qtSet[qt[i]] = 1;

    var best = null;
    var bestScore = 0;
    var bestInter = 0;

    for (var j = 0; j < CATALOG.length; j++) {
      var e = CATALOG[j];
      var inter = 0;
      var tok = e._tok;
      for (var k = 0; k < tok.length; k++) {
        if (qtSet[tok[k]]) inter++;
      }
      if (inter === 0) continue;

      var union = qt.length + tok.length - inter;
      var score = inter / (union || 1);

      var brandTok = tokens(e.b || '');
      for (var b = 0; b < brandTok.length; b++) {
        if (qtSet[brandTok[b]]) { score += 0.18; break; }
      }

      var keyHit = 0;
      for (var k2 = 0; k2 < tok.length; k2++) {
        if (qtSet[tok[k2]] && KEY_WORDS[tok[k2]]) keyHit++;
      }
      score += 0.08 * keyHit;

      if (score > bestScore || (score === bestScore && inter > bestInter)) {
        bestScore = score;
        bestInter = inter;
        best = e;
      }
    }

    if (!best || bestScore < minScore || bestInter < minInter) return null;
    return best.i || null;
  }

  function findImageDetailed(descripcion, marca, opts) {
    opts = opts || {};
    var minScore = opts.minScore != null ? opts.minScore : 0.45;
    var minInter = opts.minInter != null ? opts.minInter : 2;
    var query = (marca ? marca + ' ' : '') + (descripcion || '');
    var qt = tokens(query);
    if (!qt.length) return null;
    var qtSet = {};
    for (var i = 0; i < qt.length; i++) qtSet[qt[i]] = 1;
    var best = null, bestScore = 0, bestInter = 0;
    for (var j = 0; j < CATALOG.length; j++) {
      var e = CATALOG[j];
      var inter = 0;
      for (var k = 0; k < e._tok.length; k++) if (qtSet[e._tok[k]]) inter++;
      if (!inter) continue;
      var union = qt.length + e._tok.length - inter;
      var score = inter / (union || 1);
      var brandTok = tokens(e.b || '');
      for (var b = 0; b < brandTok.length; b++) if (qtSet[brandTok[b]]) { score += 0.18; break; }
      var keyHit = 0;
      for (var k2 = 0; k2 < e._tok.length; k2++) if (qtSet[e._tok[k2]] && KEY_WORDS[e._tok[k2]]) keyHit++;
      score += 0.08 * keyHit;
      if (score > bestScore || (score === bestScore && inter > bestInter)) {
        bestScore = score; bestInter = inter; best = e;
      }
    }
    if (!best || bestScore < minScore || bestInter < minInter) return null;
    return { url: best.i, score: bestScore, inter: bestInter, brand: best.b, desc: best.d };
  }

  function enrichItem(item) {
    if (!item) return item;
    if (item.imagen_url || item.imagen || item.image_url || item.Imagen) {
      item.imagen_url = item.imagen_url || item.imagen || item.image_url || item.Imagen;
      return item;
    }
    var desc = item.Producto || item.descripcion || item.InventarioProductoDescripcion || item.Descripcion || '';
    var marca = item.Marca || item.marca || item.InventarioProductoProveedorNombre || '';
    var url = findImage(desc, marca);
    if (url) item.imagen_url = url;
    return item;
  }

  function enrichList(list) {
    if (!list || !list.length) return list;
    for (var i = 0; i < list.length; i++) enrichItem(list[i]);
    return list;
  }

  /**
   * Sincroniza imagen_url en Supabase para todos los productos del catálogo local.
   * Requiere que exista la columna imagen_url.
   * @param {object} supabaseClient - cliente supabase-js
   * @param {Array} products - lista currentData
   * @param {function} [onProgress] - (done, total, matched)
   * @returns {Promise<{matched:number, updated:number, errors:string[]}>}
   */
  async function syncToSupabase(supabaseClient, products, onProgress) {
    if (!supabaseClient) throw new Error('Falta cliente Supabase');
    if (!products || !products.length) return { matched: 0, updated: 0, errors: ['Sin productos'] };

    var toUpdate = [];
    for (var i = 0; i < products.length; i++) {
      var item = products[i];
      var codigo = item.Codigo || item.codigo || item.InventarioProductoCodigo || '';
      if (!codigo) continue;
      var desc = item.Producto || item.descripcion || item.InventarioProductoDescripcion || '';
      var marca = item.Marca || item.marca || '';
      // Preferir URL ya guardada; si no, calcular
      var url = item.imagen_url || findImage(desc, marca);
      if (url) {
        item.imagen_url = url;
        toUpdate.push({ codigo: String(codigo), imagen_url: url });
      }
    }

    var updated = 0;
    var errors = [];
    var BATCH = 20;
    for (var b = 0; b < toUpdate.length; b += BATCH) {
      var chunk = toUpdate.slice(b, b + BATCH);
      for (var c = 0; c < chunk.length; c++) {
        var row = chunk[c];
        try {
          var res = await supabaseClient
            .from('productos')
            .update({ imagen_url: row.imagen_url, actualizado_en: new Date().toISOString() })
            .eq('codigo', row.codigo);
          if (res.error) {
            // Columna inexistente
            if (/imagen_url/i.test(res.error.message || '')) {
              throw new Error('Falta la columna imagen_url. Ejecuta en SQL Editor:\nALTER TABLE productos ADD COLUMN IF NOT EXISTS imagen_url text;');
            }
            errors.push(row.codigo + ': ' + (res.error.message || res.error));
          } else {
            updated++;
          }
        } catch (err) {
          errors.push(row.codigo + ': ' + (err.message || err));
          if (/Falta la columna/i.test(err.message || '')) {
            return { matched: toUpdate.length, updated: updated, errors: errors };
          }
        }
      }
      if (typeof onProgress === 'function') {
        onProgress(Math.min(b + BATCH, toUpdate.length), toUpdate.length, toUpdate.length);
      }
    }
    return { matched: toUpdate.length, updated: updated, errors: errors };
  }

  global.LaiveImages = {
    catalog: CATALOG,
    findImage: findImage,
    findImageDetailed: findImageDetailed,
    enrichItem: enrichItem,
    enrichList: enrichList,
    syncToSupabase: syncToSupabase
  };
